styles:
.b-faq {
    container-type: inline-size;
}

.b-faq__title {
    margin: 0 0 1em;
}

.b-faq__filter {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5em;
    margin: 0 0 1.25em;
}

/* A flex box outranks the browser's own [hidden] rule. */
.b-faq__filter[hidden],
.b-faq__item[hidden] {
    display: none;
}

.b-faq__chip {
    font: inherit;
    color: inherit;
    background: none;
    border: 1px solid currentColor;
    border-radius: 999px;
    padding: 0.35em 0.9em;
    cursor: pointer;
    opacity: 0.65;
}

.b-faq__chip.is-active {
    opacity: 1;
    font-weight: 600;
}

.b-faq__item {
    border-top: 1px solid color-mix(in srgb, currentColor 20%, transparent);
}

.b-faq__item:last-child {
    border-bottom: 1px solid color-mix(in srgb, currentColor 20%, transparent);
}

.b-faq__question {
    cursor: pointer;
    padding: 1em 0;
    font-weight: 600;
}

.b-faq__answer {
    padding: 0 0 1em;
}

.b-faq__answer > :first-child {
    margin-top: 0;
}

.b-faq__answer > :last-child {
    margin-bottom: 0;
}

.b-faq__answer img {
    max-width: 100%;
    height: auto;
}

script:
const items = Array.from(el.querySelectorAll('.b-faq__item'))
const chips = Array.from(el.querySelectorAll('.b-faq__chip'))
const filter = el.querySelector('.b-faq__filter')

// The filter is printed hidden: without this script its buttons would do nothing.
if (filter) filter.hidden = false

const show = (group) => {
  for (const chip of chips) {
    const on = (chip.dataset.faqGroup || '') === group
    chip.classList.toggle('is-active', on)
    chip.setAttribute('aria-pressed', on ? 'true' : 'false')
  }
  for (const item of items) {
    const groups = (item.dataset.faqCategories || '').split(' ')
    item.hidden = group !== '' && !groups.includes(group)
  }
}

for (const chip of chips) {
  chip.addEventListener('click', () => show(chip.dataset.faqGroup || ''))
}

// A link to #anchor opens its question, even when a filter had hidden it.
const open = () => {
  const id = decodeURIComponent(location.hash.slice(1))
  const item = id === '' ? undefined : items.find((candidate) => candidate.id === id)
  if (!item) return
  if (item.hidden) show('')
  item.open = true
  item.scrollIntoView({ block: 'start' })
}

open()
window.addEventListener('hashchange', open)
